#!/usr/bin/env python3
"""Раздел 1.5: UML-модели представления (по одной диаграмме каждого вида), без подразделов.
Использование: python3 build_15.py выход.docx
"""
import os, sys
import docx
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Builder

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
KURS = os.path.join(ROOT, 'docs', 'kursovaya')
d = docx.Document(os.path.join(KURS, 'src', 'er-part.docx'))
P = d.paragraphs
b = Builder(d, P[1], P[4], P[6])
body = d.element.body
for el in list(body):
    if not el.tag.endswith('sectPr'):
        body.remove(el)
img = lambda n: os.path.join(KURS, f'view-{n}.png')

b.heading('1.5 UML-модели представления программного средства и их описание')
b.para('Модели представления показывают программное средство с разных точек зрения: кто и для чего им пользуется, как взаимодействуют его части, в какой последовательности выполняются действия, какие состояния принимает объект и как система размещается на оборудовании. Для описания использован унифицированный язык моделирования UML, построено по одной диаграмме каждого вида. Диаграммы последовательности, деятельности и состояний посвящены оформлению кредита – наиболее сложному процессу системы (подраздел 1.2). Диаграмма классов и ER-диаграмма приведены в подразделе 1.4.')
b.para('Диаграмма вариантов использования (рисунок 1.15) показывает функции системы с точки зрения внешних участников. Актёры соответствуют участникам процесса из таблицы 1.2. Гость просматривает курсы валют, пользуется калькуляторами и подаёт анкету. Клиент после проверки анкеты работает со счетами, переводами, платежами, вкладами, кредитами и картами; подача заявки на кредит включает скоринг, а перевод и подписание кредитного договора включают подтверждение одноразовым кодом. Сотрудники банка работают в рабочих местах, состав которых определяется ролью, администратор настраивает систему и контролирует её работу.')
b.figure(img('uc'), 'Рисунок 1.15 – Диаграмма вариантов использования', width=24.5, max_h=16.2)
b.para('Последовательность оформления кредита показана на рисунке 1.16. Контроллер принимает заявку клиента и вызывает сервис кредитов. Сервис рассчитывает график платежей и долговую нагрузку и передаёт данные сервису скоринга, который возвращает вероятность дефолта. При вероятности до 8 % и сумме в пределах лимита заявка одобряется автоматически, при вероятности до 30 % её рассматривает кредитный специалист, в остальных случаях выдаётся отказ. Одобренную заявку клиент подписывает кодом из письма, который выдаёт и проверяет сервис одноразовых кодов, после чего сервис учёта выполняет проводку выдачи кредита.')
b.figure(img('seq-loan'), 'Рисунок 1.16 – Диаграмма последовательности: заявка на кредит')
b.para('Порядок действий и их распределение между участниками показаны на рисунке 1.17. Диаграмма деятельности дополняет функциональную модель из подраздела 1.2. Система рассчитывает график и долговую нагрузку: при нагрузке выше 40 % следует отказ. Затем скоринг определяет вероятность дефолта и направляет заявку по одной из ветвей: автоодобрение, ручное рассмотрение кредитным специалистом или отказ. После одобрения клиент подписывает договор кодом, и система выдаёт кредит: открывает ссудный счёт, формирует график и зачисляет деньги.')
b.figure(img('act-loan'), 'Рисунок 1.17 – Диаграмма деятельности: оформление кредита')
b.para('Состояния заявки на кредит показаны на рисунке 1.18, названия состояний совпадают со значениями поля статуса в базе данных. Заявка получает начальное состояние по результату проверки: approved при автоодобрении, manual_review при ручном рассмотрении, rejected при отказе. Специалист переводит заявку из manual_review в approved или rejected. Одобренная заявка после подписания договора кодом становится signed.')
b.figure(img('st-loan'), 'Рисунок 1.18 – Диаграмма состояний: заявка на кредит')
b.para('Структура программного средства показана на диаграмме компонентов (рисунок 1.19). Браузер получает страницы и клиентский JavaScript по HTTPS. На сервере запрос проходит через промежуточные слои (сессии, защита от подделки запросов, проверка прав, обязательная двухфакторная защита сотрудников), затем маршруты передают его контроллеру. Контроллер вызывает сервисы с бизнес-логикой и формирует ответ с помощью представлений EJS. Сервисы работают с базой данных PostgreSQL через модели с SQL-запросами, получают курсы валют по HTTPS от Национального банка и отправляют письма через SMTP-сервер. Фоновые задачи создают зашифрованные резервные копии и отправляют письма из очереди.')
b.figure(img('components'), 'Рисунок 1.19 – Диаграмма компонентов')
b.para('Размещение программного средства на оборудовании показано на диаграмме развёртывания (рисунок 1.20). Клиент работает в браузере на своём компьютере и обращается к серверу приложения по протоколу HTTPS: перед приложением стоит обратный прокси-сервер с сертификатом TLS. Приложение на Node.js обращается к серверу базы данных по протоколу PostgreSQL, к почтовому серверу по SMTP и к интерфейсу Национального банка за курсами валют. Резервные копии базы данных шифруются алгоритмом AES-256-GCM и хранятся отдельно от рабочей базы.')
b.figure(img('deployment'), 'Рисунок 1.20 – Диаграмма развёртывания')
d.save(sys.argv[1])
